import React from 'react';

import { useNavigate } from 'react-router-dom';

import { getEquipSets, getOneBackpackAsync } from '@apps/Hiking/@services/equip.service';
import { IBackpack, IEquipSetListItem } from '@apps/Hiking/@types/equip.types';
import { editBackpackAsync } from '@apps/Hiking/equip/BackpackEditor/backpackEditorHelper';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import BackpackVertical from '../components/BackpackVertical';
import EquipSetListItem from '../components/EquipSetListItem';

const EquipPageBackpackOne: React.FC<{ id_backpack: number }> = ({ id_backpack }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IBackpack>();
  const [sets, setSets] = React.useState<IEquipSetListItem[]>([]);

  const navigate = useNavigate();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getOneBackpackAsync(id_backpack);
      setData(res);
      const res1 = await getEquipSets({ id_backpack });
      setSets(res1);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_backpack]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data) return <PohAlert variant={AlertVariant.Danger}>no backpack</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/equip', text: 'Снаряжение' },
          { href: '/equip/backpacks', text: 'Рюкзаки' },
          { href: '/equip/backpacks/' + data.id, text: data.name, active: true },
        ]}
      />

      <PohContainer>
        <PohRow>
          <PohCol sm={3}>
            <PohButton
              className="float-end"
              icon={IconsEnum.edit}
              onClick={async () => {
                const up = await editBackpackAsync(data);
                up && setData(up);
              }}
            />
            <BackpackVertical backpack={data}></BackpackVertical>
          </PohCol>
          <PohCol sm={9}>
            <h5>Сборки под этот рюкзак</h5>
            {!sets.length && <Empty>Нет сборок для этого рюкзака</Empty>}
            {sets.length > 0 && (
              <PohList
                data={sets.map((s) => {
                  return {
                    key: s.id,
                    children: <EquipSetListItem item={s} />,
                    action: true,
                    onClick: () => navigate(`/equip/sets/${s.id}`),
                  };
                })}
              />
            )}
          </PohCol>
        </PohRow>
      </PohContainer>
    </div>
  );
};

export default EquipPageBackpackOne;
